function hash(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function rng(seed){let a=seed;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function semana(){const d=new Date(),o=new Date(d.getFullYear(),0,1);return d.getFullYear()+'-S'+Math.ceil(((d-o)/864e5+o.getDay()+1)/7)}
const verano=m=>m>=9||m<=2, playeras=m=>m>=8||m<=3;
function nota(m){return verano(m)?'Llegaron los migrantes de verano: golondrinas, vencejos, cuclillos y playeros del norte.':'Invierno: se fueron los migrantes de verano y las sierras altas están heladas.'}
// probabilidad de que una especie aparezca en una salida a la zona zi en el mes m
const K=2.2,ZC={U:'#c9d6a8',P:'#e4d5a0',L:'#b4d8da',E:'#e0cfa8',R:'#b4cde3',C:'#dcc7a2',A:'#cfd3da',H:'#e6c8d2',M:'#e8c9a4'};
