// f = % de las listas de eBird en Córdoba que registran la especie. q = cuánto se concentra en cada zona.
function prob(i,zi,m){const x=SP[i];let p=x[4]/100*x.q[zi]*(G&&G.P?G.P.K:K)*ZM[ZK[zi]];if(x[6]===1)p*=verano(m)?1.9:.04;if(x[6]===2)p*=playeras(m)?1.7:.05;if(ZK[zi]==='A'&&m>=4&&m<=7)p*=.6;return .8*(1-Math.exp(-p/.8))}
