function chips(o){if(!G.P.pistas)return '';const c=[];
 if(o.ef>=1.15)c.push(['up','Más aves']);else if(o.ef&&o.ef<=.9)c.push(['dn','Menos aves']);
 if(o.ari>=1.15)c.push(['ra','Más chance de raras']);else if(o.ari&&o.ari<1)c.push(['dn','Menos raras']);
 if(o.rara!=null)c.push(['ra','Chance de una rara']);
 if(o.fam)c.push(['up','Más '+FAMS[o.fam[0][0]].split(',')[0].toLowerCase()]);
 if(o.az)c.push(['rs','Puede salir mal o muy bien']);
 return c.length?`<span class="chips">${c.map(x=>`<i class="${x[0]}">${x[1]}</i>`).join('')}</span>`:''}

