function pop(t,bad,s){if(window.SIMULA||!t)return;sfx(s||(bad?'mal':'bien'));const d=document.createElement('div');d.className='pop'+(bad?' mal':'');d.textContent=t;document.body.appendChild(d);setTimeout(()=>d.remove(),1700)}
function deltas(o){const a=[];if(o.na)a.push((o.na>0?'+':'−')+Math.abs(o.na)+' nafta');if(o.en)a.push((o.en>0?'+':'−')+Math.abs(o.en)+' energía');return a.join(' · ')}
function viaje2(){clearTimeout(G.tm);
 const rr=G.r();G.kind='ev';if(G.k>0&&rr>=G.P.mi&&rr<G.P.mi+G.P.su){G.kind='su';return suerte()}
 if(G.k>0&&rr<G.P.mi){G.kind='mi';let pm=MI.filter(m=>!m.x||G.P.exp),pool=pm.filter(m=>!G.mis.has(m.id));if(!pool.length){G.mis.clear();pool=pm}const m=pool[Math.floor(G.r()*pool.length)];G.mis.add(m.id);G.mi=m;
  return $(cab()+`<div class="vig">${VIG[m.vig||m.id]}</div><div><p class="lab">${MESES[G.mes]} · ${G.lugar.n}</p><h2>${m.q}</h2></div><div class="ops">${m.o.map((o,k)=>{const bl=(o.en<0&&G.en+o.en<0)||(o.na<0&&G.nafta+o.na<0),todos=m.o.every(x=>(x.en<0&&G.en+x.en<0)||(x.na<0&&G.nafta+x.na<0)),no=bl&&!(todos&&k===m.o.length-1);return `<button class="op" style="--r:${k?.5:-.5}deg" ${no?'disabled':''} onclick="elegirMi(${k})"><b>${o.t}</b><span>${o.s}</span><small>${o.c}${no?' · no te alcanza':''}</small></button>`}).join('')}</div>`)}
 evento()}
function elegirMi(k){const o=G.mi.o[k];let bad=false,t=deltas(o);
 if(o.en)G.en=Math.max(0,Math.min(4,G.en+o.en));if(o.na)G.nafta=Math.max(0,G.nafta+o.na);
 if(o.mod){G.mod*=o.mod;t+=(t?' · ':'')+'rendís menos';bad=true}
 if(o.az){const mal=G.r()<o.az[0];G.mod*=mal?o.az[1]:o.az[2];if(mal){G.nafta=Math.max(0,G.nafta+(o.naMal||0));t=o.az[3];bad=true}else t=o.az[4]}
 if(o.na<0||o.en<0)bad=true;
 pop(t,bad);G.ev={w:'day',o:[]};resolver({})}
function elegirZona(i){G.mod=1;G.ari=1;G.lugar=G.ops[i];G.zona=G.lugar.z;G.vis.add(G.lugar.n);G.nafta-=G.lugar.c;viaje2()}
function gscore(fi,zi){let s=0;for(let i=0;i<N;i++){const x=SP[i];if(x[3]===fi&&!G.vistas.has(x[0]))s+=prob(i,zi,G.mes)*MK(G.lugar)}return s}
function expertoEv(ev){const zi=ZK.indexOf(G.zona),sc=FAMS.map((n,fi)=>[fi,gscore(fi,zi),SP.filter(x=>x[3]===fi).length]).filter(a=>a[2]>=3).sort((a,b)=>b[1]-a[1]);
 const top=sc.slice(0,3),mal=sc.slice(-8),buena=G.r()<.6,pk=buena?top[Math.floor(G.r()*top.length)]:mal[Math.floor(G.r()*mal.length)];
 const o=[...ev.o,{t:'Especializarte en '+FAMS[pk[0]].toLowerCase(),s:'Dedicás la jornada a ese grupo.',c:'Sin costo',ef:.8,fam:[[pk[0]],3.5]},{t:'Buscar a las más esquivas',s:'Poco movimiento y mucha paciencia: las comunes pasan de largo.',c:'−1 energía',en:-1,ef:.7,ari:3.5}];if(G.k<=8&&(G.permM||1)<1.5&&G.r()<.6)o.push({t:'Estudiar el terreno y sus aves',s:'Hoy salís a medias, pero aprendés para el resto del año.',c:'−1 energía · hoy rendís menos',en:-1,ef:.55,perm:1.14});if(G.r()<.5)o.push({t:'Apostar por una rara',s:'Esperás una sola especie durante horas.',c:'−1 energía',en:-1,ef:.55,rara:.5});
 for(let i=o.length-1;i>0;i--){const j=Math.floor(G.r()*(i+1));[o[i],o[j]]=[o[j],o[i]]}return Object.assign({},ev,{o})}
function evento(){clearTimeout(G.tm);
 const ok=(e)=>(!e.z||e.z.includes(G.zona))&&(!e.x||G.P.exp);
 let pool=G.evs.filter(j=>ok(EV[j]));if(!pool.length){G.evs=EV.map((_,j)=>j);pool=G.evs.filter(j=>ok(EV[j]))}
 const j=pool[Math.floor(G.r()*pool.length)];G.evs.splice(G.evs.indexOf(j),1);G.ev=G.P.exp?expertoEv(EV[j]):EV[j];
 $(cab()+escena(G.zona,G.ev.w,nota(G.mes))+`<div><p class="lab">${MESES[G.mes]} · ${G.lugar.n}</p><h2>${G.ev.q}</h2></div>
 ${tip(TIPS[3])}<div class="ops">${G.ev.o.map((o,k)=>{const bl=o=>(o.en<0&&G.en+o.en<0)||(o.na<0&&G.nafta+o.na<0),todos=G.ev.o.every(bl),no=bl(o)&&!(todos&&k===G.ev.o.length-1);return `<button class="op" ${no?'disabled':''} onclick="elegirEv(${k})"><b>${o.t}</b><span>${o.s}</span>${chips(o)}<small>${G.P.pistas||/energía|nafta/.test(o.c)?o.c:''}${no?' · no te alcanza':''}</small></button>`}).join('')}</div>`)}
function elegirEv(k){resolver(G.ev.o[k])}
function resolver(o){if(o.perm){G.permM=(G.permM||1)*o.perm;pop('Aprendiste del lugar: rendís más el resto del año')}if(o.en<0||o.na<0)pop(deltas(o),true);let ef=(o.ef||1)*(G.mod||1)*(G.permM||1),msg='';
 if(o.en)G.en=Math.max(0,Math.min(4,G.en+o.en));if(o.na)G.nafta=Math.max(0,G.nafta+o.na);
 if(o.az){const mal=G.r()<o.az[0];ef=mal?o.az[1]:o.az[2];msg=mal?o.az[3]:o.az[4]}
 if(G.P.amp)ef=Math.pow(ef,ef<1?G.P.amp[0]:G.P.amp[1]);if(G.en===0){ef*=G.P.exp?.55:.8;msg+=(msg?' ':'')+'Estás fundido: rendís menos hasta que descanses.'}
 const zi=ZK.indexOf(G.zona),nuevas=[];let rep=0;
 for(let i=0;i<N;i++){const x=SP[i];if(x[4]<G.P.fmin)continue;let e=ef;if(o.ari&&x[4]<2)e*=o.ari;if(G.ari>1&&x[4]<2)e*=G.ari;if(o.fam&&o.fam[0].includes(x[3]))e*=o.fam[1];
  const p=1-Math.pow(1-Math.min(.8,prob(i,zi,G.mes)*MK(G.lugar)),e);if(G.r()<p){if(G.vistas.has(x[0]))rep++;else{G.vistas.add(x[0]);nuevas.push(i)}}}
 if(o.rara!=null){if(G.r()<o.rara){const cand=SP.map((x,i)=>i).filter(i=>!G.vistas.has(SP[i][0])&&SP[i][4]<Math.max(1.5,G.P.fmin*3)&&SP[i][4]>=Math.max(.02,G.P.fmin)),wt=i=>Math.sqrt(SP[i][4]);const tot=cand.reduce((a,i)=>a+wt(i),0);let u=G.r()*tot,pick=null;for(const i of cand){u-=wt(i);if(u<=0){pick=i;break}}if(pick!=null){G.vistas.add(SP[pick][0]);nuevas.unshift(pick);msg='Estaba. Dos horas de ruta y ahí la tenías: '+SP[pick][1]+'.'}}else msg='Llegaste y ya no estaba. Así es esto.'}
 if(G.mod<1)msg+=(msg?' ':'')+'Saliste en desventaja este mes.';
 nuevas.sort((a,b)=>SP[a][4]-SP[b][4]);if(!window.SIMULA)nuevas.slice(0,5).forEach((_,k)=>setTimeout(()=>sfx('ave'),350+k*200));
 G.log.push({m:G.mes,z:G.lugar.n,n:nuevas.length,ids:nuevas});
 const fin=G.k===G.P.cal.length-1;
 $(cab()+escena(G.zona,G.ev.w,'')+`<div><p class="lab">${MESES[G.mes]} · ${G.lugar.n}</p><h2>${nuevas.length?'+'+nuevas.length+' especie'+(nuevas.length>1?'s':'')+' nueva'+(nuevas.length>1?'s':''):'Nada nuevo esta vez'}</h2><p class="sub">${rep} repetidas. Llevás ${G.vistas.size} en el año.</p></div>
 ${msg?`<p class="nota">${msg}</p>`:''}
 <div class="figus">${nuevas.slice(0,60).map(figu).join('')}</div>${nuevas.length>60?`<p class="pie">…y ${nuevas.length-60} más que ya quedaron en tu libreta.</p>`:''}
 <button class="btn" onclick="${fin?'final()':'sig()'}">${fin?'Cerrar el año':'Siguiente mes'}</button>`);revelar(nuevas.filter(i=>SP[i][4]<.5).sort((a,b)=>SP[b][4]-SP[a][4]))}
const AVE='<svg viewBox="0 0 40 40" aria-hidden="true"><ellipse cx="19" cy="25" rx="12" ry="8"/><circle cx="29" cy="15" r="5.5"/><path d="M33 13.5l7 2.5-7 3z"/><path d="M9 24L1 31l11-3z"/></svg>';
const pc=v=>(v>=10?Math.round(v):v>=1?v.toFixed(1):v>=.1?v.toFixed(2):v.toFixed(3)).toString().replace('.',',')+' %';
function figu(i,n){const s=SP[i],rara=s[4]<.5,mit=s[4]<.05;return `<div class="figu${mit?' mit':rara?' rara':''}" style="--r:${((s[0]*37)%7-3)*.6}deg;--d:${Math.min((n||0)*.03,.8)}s" title="${s[2]}"><div class="ph" style="background:${ZC[s.zb]}"><span class="sil s-${silDe(i)}"></span></div><em>${s[1]}</em><small>${pc(s[4])}</small></div>`}
function reiniciar(b){if(b.dataset.ok){clearTimeout(G&&G.tm);perfil()}else{b.dataset.ok=1;b.textContent='¿Seguro? Tocá de nuevo';setTimeout(()=>{if(b.isConnected){delete b.dataset.ok;b.textContent='Reiniciar'}},3000)}}
function sig(){G.k++;G.mes=G.P.cal[G.k];pintarMes()}
function titulo(n){const T=G.P.T;return n>=T[4]?'Leyenda cordobesa':n>=T[3]?'Cazador de lifers':n>=T[2]?'Ojo entrenado':n>=T[1]?'Libreta gastada':n>=T[0]?'Salidor de domingo':'Pajarero de balcón'}
function final(){const n=G.vistas.size,top=[...G.vistas].map(id=>IX[id]).sort((a,b)=>SP[a][4]-SP[b][4]).slice(0,6),mejor=G.log.slice().sort((a,b)=>b.n-a.n)[0];
 const txt=`${NOMBRE?'El año pajarero de '+NOMBRE:'Mi año pajarero'} (${G.P.n})\n${n} especies de Córdoba ${G.P.fin} · ${titulo(n)}\nMejor mes: ${MESES[mejor.m]} en ${mejor.z} (+${mejor.n})\nFigurita más difícil: ${SP[top[0]][1]}\n¿Me ganás? ${SH.url}`;
 $(`<div><p class="lab">Fin del año</p><div class="grande">${n}<small> especies</small></div><h2>de Córdoba ${G.P.fin}</h2></div>
 <span class="sello">${titulo(n)}</span>
 <div class="comp"><button class="btn big" id="bsh" onclick="compartir()" disabled>Preparando imagen…</button>
 <canvas id="cv" class="cv" aria-label="Imagen para compartir tu resultado"></canvas>
 <div class="fmt"><span>Formato</span>${Object.keys(FMT).map(k=>`<button data-f="${k}" onclick="elegirFmt('${k}')">${FMT[k].n}</button>`).join('')}<button class="lnk" id="bdl" onclick="descargar()" style="display:none">Descargar</button></div>
 </div>
 <p class="sub">Te sobraron ${G.nafta} de nafta.</p>
 <div><p class="lab" style="margin-bottom:8px">Tus figuritas más difíciles</p><div class="figus">${top.map((i,k)=>figu(i,k)).join('')}</div></div>
 <div><p class="lab" style="margin-bottom:6px">Tu camino</p><div class="recap">${G.log.map(l=>`<div><span>${MESES[l.m]} · ${l.z}</span><b>+${l.n}</b></div>`).join('')}</div></div>
 <div class="lnks"><button class="lnk" onclick="nuevo(String(Math.random()),G.modo)">Jugar otra vez</button><button class="lnk" onclick="perfil()">Cambiar de perfil</button><button class="lnk" id="cp" onclick="copiar()">Copiar texto</button></div><textarea id="txt" rows="4" readonly style="display:none">${txt}</textarea>
 <p class="pie"><a href="/">Volver a la web</a> · Frecuencias: eBird, 85.637 listas completas de Córdoba. El porcentaje de cada figurita es en cuántas listas aparece.</p>`);SH.d={n,top,titulo:titulo(n),nombre:NOMBRE,perfil:G.P.n,fin:G.P.fin,salidas:G.P.cal.length};SH.txt=txt;elegirFmt('historia');sonar(1)}
function copiar(){const t=document.getElementById('txt'),b=document.getElementById('cp');const ok=()=>{b.textContent='Copiado'};
 (navigator.clipboard?navigator.clipboard.writeText(t.value):Promise.reject()).then(ok).catch(()=>{t.style.display='block';t.focus();t.select();b.textContent='Seleccionado: copialo'})}
function perfil(){document.getElementById('app').dataset.s='';$(`<div><p class="lab">Antes de salir</p><h2>¿Quién sale a pajarear?</h2></div>
 <input id="nom" class="nom" type="text" maxlength="16" placeholder="Tu nombre (opcional)" value="${NOMBRE.replace(/"/g,'')}" autocomplete="given-name">
 <div><p class="lab" style="margin-bottom:8px">Elegí tu perfil</p><div class="ops">${Object.keys(PERF).map((k,i)=>`<button class="op" style="--r:${[-.6,.5,-.3][i]}deg" onclick="empezar('${k}')"><b>${PERF[k].n}</b><span>${PERF[k].d}</span><small>${PERF[k].t}</small></button>`).join('')}</div></div>`)}
function empezar(m){const v=(document.getElementById('nom')||{}).value||'';NOMBRE=v.trim().slice(0,16);try{localStorage.setItem('pajarero_nombre',NOMBRE)}catch(e){}if(SND)musica(true);cargarCantos();nuevo(String(Math.random()),m)}
function slides(){const ks=['pastizal','humedal','sierras','bosque','arbustal','ocaso'];return `<div class="slides" id="sls">${ks.map((k,i)=>`<div class="sl${i?'':' on'}" style="background-image:url(data:image/svg+xml;base64,${IMG[k]})"></div>`).join('')}</div>`}
function filaRand(){const P=[[],[],[]];SP.forEach((x,i)=>P[x[4]<.5?0:x[4]<5?1:2].push(i));const pk=(L,n)=>{const o=[];while(o.length<n){const i=L[Math.floor(Math.random()*L.length)];if(!o.includes(i))o.push(i)}return o};const f=[...pk(P[0],2),...pk(P[1],4),...pk(P[2],6)];for(let i=f.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[f[i],f[j]]=[f[j],f[i]]}const h=f.map(i=>figu(i,0)).join('');return h+h}
function pasar(){const r=document.getElementById('sls');if(!r)return;if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;let i=0;const t=setInterval(()=>{if(!document.body.contains(r)){clearInterval(t);return}const L=r.children,c=L[i],n=L[(i+1)%L.length];n.style.transition='none';n.className='sl';void n.offsetWidth;n.style.transition='';n.className='sl on';c.className='sl out';i=(i+1)%L.length},3200)}
function inicio(){
 $(`<div><h1 class="hl">${LOGO}</h1><p class="sub">Salís a pajarear por Córdoba, tomás decisiones y armás tu libreta de especies. ¿Cuántas lográs sumar?</p></div>
 ${slides()}
 <p>Elegís a dónde salir y resolvés lo que te cruza el camino. Cada lugar tiene sus aves, y muchas cambian con las estaciones. Lo que encontrás se sortea con la frecuencia real de eBird: ningún año se repite.</p>
 <div class="marq"><div class="mt">${filaRand()}</div></div>
 <button class="btn" onclick="perfil()">Empezar</button>`);pasar()}
inicio();
